// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on XY plane (z = 0), neck builds upward (+Z)

// ---------------- Parameters ----------------
flange_width   = 12;   // flange width along Y (mm)
flange_thick   = 2.5;  // flange thickness along Z (mm), z = 0 .. 2.5
neck_width     = 6;    // neck width along Y (mm)
neck_top_z     = 5.5;  // top of neck along Z (mm)
screw_d        = 3.4;  // central screw hole diameter (mm)
length_x       = 10;   // part length along X (mm), centred on origin
eps            = 0.5;  // overshoot for clean boolean cuts (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Upside-down T profile, centred in X and Y
    union() {
        // Bottom flange
        translate([-length_x / 2, -flange_width / 2, 0])
            cube([length_x, flange_width, flange_thick]);

        // Neck, centred on flange, rising from z = 0 to z = neck_top_z
        translate([-neck_width / 2, 0, 0])
            cube([neck_width, flange_thick + neck_top_z - flange_thick,
                  neck_top_z]);
    }

    // Vertical through-hole for screw
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_thick + neck_top_z + 2 * eps);
}
