// T-shaped nut for aluminium extrusion
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z)
// Placed using the user's coordinates: X 0..10, Y -6..6, Z 0..5.5

// ---- Dimensions (mm) ----
flange_w     = 12;   // flange width (Y)
flange_t     = 2.5;  // flange thickness (Z), z = 0..2.5
neck_w       = 6;    // neck width (Y)
neck_h       = 3;    // neck height above flange top (z = 3..5.5)
screw_d      = 3.4;  // central screw hole diameter
x_len        = 10;   // part length along X
overlap      = 0.01; // small overlap so flange and neck fuse cleanly

$fn = 64;

difference() {
    union() {
        // Bottom flange
        translate([0, -flange_w/2, 0])
            cube([x_len, flange_w, flange_t]);

        // Neck, centred on the flange in X and Y
        translate([0, 0, flange_t - overlap])
            cube([x_len, neck_w, neck_h + overlap]);
    }

    // Vertical screw hole through the whole part
    translate([0, 0, -overlap])
        cylinder(d = screw_d, h = flange_t + neck_h + 2*overlap);
}
