plate_len   = 50;    // plate length along X (mm)
plate_wid   = 30;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle cylinder diameter (mm)
knuckle_z   = 4;     // knuckle axis height above bed (mm)
knuckle_n   = 5;     // number of segments along plate length
knuckle_pitch = plate_len / knuckle_n; // segment length (10 mm)
knuckle_hole = 3;    // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Derived ----------------
knuckle_count = 3;   // 1st, 3rd, 5th segments only
knuckle_x0    = -knuckle_pitch * (knuckle_count - 1) / 2; // first knuckle X (centres set)

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles: cylinders whose axes run along X at y = 15, z = 4
    for (i = [0 : knuckle_count - 1]) {
        translate([knuckle_x0 + i * knuckle_pitch, 15, 0])
            difference() {
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = plate_len + 2*eps, center = true); // cylinder spans beyond plate
                translate([0, 0, -eps])
                    cylinder(d = knuckle_hole, h = plate_len + 2*eps + 2*eps, center = true); // pin hole through full length
            }
    }
}
