knuckle_h   = 16;    // length of knuckle cylinder along X (mm)
knuckle_hole = 3;    // pin hole diameter (mm)

segment_n   = 5;     // number of equal segments along plate length
segment_w   = plate_len / segment_n;  // segment width (10 mm)

eps         = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 96;            // curve resolution

// ---------------- Derived ----------------
knuckle_count = 3;   // 1st, 3rd, 5th segments have knuckles

