union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles
    for (i = [0 : knuckle_count - 1]) {
        x = (i % 2) * (segment_w * 2 - segment_w) + segment_w/2;  // 10, 30, 50
        translate([x - knuckle_h/2, plate_wid/2, 0])
            difference() {
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = knuckle_h);
                translate([0, 0, -eps])
                    cylinder(d = knuckle_hole, h = knuckle_h + 2*eps);
            }
    }
