// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z)
// Positioned per the user's coordinates: x -10 to 0, y -7 to 7

$fn = 64;

// ---- Dimensions (mm) ----
flange_w      = 14;   // flange width (Y)
flange_t      = 3;    // flange thickness (Z)
neck_w        = 6;    // neck width (Y)
neck_h        = 3;    // neck height above flange (Z)
screw_d       = 3.4;  // central screw hole diameter
eps           = 0.5;  // cutter overshoot past faces

// ---- Derived ----
total_h       = flange_t + neck_h;   // 6 mm overall height
screw_z0      = -eps;                // hole start below flange
screw_z1      = total_h + eps;       // hole end above neck

// ---- Model ----
difference() {
    union() {
        // Bottom flange
        translate([-10, -flange_w / 2, 0])
            cube([flange_w, 20, flange_t]);   // 20 mm X length (user gave -10 to 0)
        // Neck (overlaps flange slightly for a clean union)
        translate([-10 + eps, -neck_w / 2, flange_t - 0.01])
            cube([flange_w - 2 * eps, neck_w, neck_h + 0.01]);
